import React, { useEffect, useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import AOS from "aos";

import img1 from "./assests/dates.jpg";
import img2 from "./assests/nuts.jpg";
import img3 from "./assests/seeds.jpg";

export default function HerbsSpicesHome() {
  const slides = [
    { image: img1, title: "Fresh Dates", offer: "FLAT 10% OFF", coupon: "DATE10" },
    { image: img2, title: "Premium Nuts", offer: "BUY 1 GET 1 FREE", coupon: "NUTS50" },
    { image: img3, title: "Organic Seeds", offer: "20% OFF", coupon: "SEED20" },
  ];

  const [index, setIndex] = useState(0);
  const [isOpen, setIsOpen] = useState(false);

  // Auto slider & AOS
  useEffect(() => {
    AOS.init({ duration: 800 });
    const timer = setInterval(() => setIndex((p) => (p + 1) % slides.length), 4000);
    return () => clearInterval(timer);
  }, []); // eslint-disable-line

  const goPrev = () => setIndex((p) => (p - 1 + slides.length) % slides.length);
  const goNext = () => setIndex((p) => (p + 1) % slides.length);

  // Close menu when link clicked (mobile)
  const handleNavClick = () => setIsOpen(false);

  return (
    <div className="position-relative w-100 vh-100 overflow-hidden">
      {/* Background Slider */}
      <div
        className="position-absolute top-0 start-0 w-100 h-100"
        style={{
          backgroundImage: `url(${slides[index].image})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          transition: "background-image 1s ease-in-out",
        }}
      />

      {/* Dark Overlay */}
      <div className="position-absolute top-0 start-0 w-100 h-100 bg-dark opacity-50"></div>

      <nav
  className="navbar navbar-expand-lg navbar-dark bg-dark bg-opacity-75 position-fixed w-100"
  style={{ top: "60px", zIndex: 2000 }}
>
  <div className="container-fluid">

    {/* Brand */}
    <a className="navbar-brand fw-bold text-warning fs-3" href="#">
      ✺ Sinthu
    </a>

    {/* Hamburger - visible only on mobile */}
    <button
      className="navbar-toggler d-lg-none"
      type="button"
      data-bs-toggle="collapse"
      data-bs-target="#mainMenu"
    >
      <span className="navbar-toggler-icon"></span>
    </button>

    {/* Menu Items */}
    <div className="collapse navbar-collapse justify-content-center" id="mainMenu">
      <ul className="navbar-nav gap-4 fs-5 fw-semibold text-center">

        <li className="nav-item d-none d-lg-block">
          <a className="nav-link" href="#">Home</a>
        </li>

        <li className="nav-item d-none d-lg-block">
          <a className="nav-link" href="#">Shop</a>
        </li>

        <li className="nav-item d-none d-lg-block">
          <a className="nav-link" href="#">Dates</a>
        </li>

        <li className="nav-item d-none d-lg-block">
          <a className="nav-link" href="#">Nuts</a>
        </li>

        <li className="nav-item d-none d-lg-block">
          <a className="nav-link" href="#">Seeds</a>
        </li>

        {/* Mobile menu items inside collapse */}
        <li className="nav-item d-lg-none"><a className="nav-link" href="#">Home</a></li>
        <li className="nav-item d-lg-none"><a className="nav-link" href="#">Shop</a></li>
        <li className="nav-item d-lg-none"><a className="nav-link" href="#">Dates</a></li>
        <li className="nav-item d-lg-none"><a className="nav-link" href="#">Nuts</a></li>
        <li className="nav-item d-lg-none"><a className="nav-link" href="#">Seeds</a></li>

      </ul>
    </div>

  </div>
</nav>


      {/* Dynamic Overlay Text */}
      <div
        className="position-relative text-center text-white d-flex flex-column justify-content-center align-items-center h-100 px-3"
        data-aos="fade-up"
        key={index}
      >
        <h1 className="display-1 fw-bold text-shadow" style={{ textShadow: "0 3px 12px rgba(0,0,0,0.6)" }}>
          {slides[index].title}
        </h1>
        <p className="fs-2 fw-semibold mt-3">{slides[index].offer}</p>
        <p className="fs-5 mt-2">
          USE COUPON : <span className="fw-bold text-warning">{slides[index].coupon}</span>
        </p>
      </div>

      {/* Left Arrow */}
      <button
        onClick={goPrev}
        className="btn btn-dark bg-opacity-75 position-absolute top-50 start-0 translate-middle-y rounded-circle p-3 fs-3"
        style={{ zIndex: 1500 }}
      >
        ❮
      </button>

      {/* Right Arrow */}
      <button
        onClick={goNext}
        className="btn btn-dark bg-opacity-75 position-absolute top-50 end-0 translate-middle-y rounded-circle p-3 fs-3"
        style={{ zIndex: 1500 }}
      >
        ❯
      </button>
    </div>
  );
}
